'use strict';
const $=id=>document.getElementById(id);
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ui={page:'today',filter:'active',selected:null,settingsTab:'appearance',data:null,pending:null,busy:false,closed:false,query:'',course:'all',sort:'asc'};
const tr=(zh,en)=>ui.data?.settings.language==='en'?en:zh;
const svg=paths=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths}</svg>`;
const icons={today:svg('<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M10 4v16"/>'),assignments:svg('<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h6"/>'),records:svg('<rect x="4" y="4" width="16" height="16" rx="2"/><path d="m8 12 3 3 6-7"/>'),notifications:svg('<path d="M5 17h14l-2-3v-4a5 5 0 0 0-10 0v4zM10 20h4"/>'),settings:svg('<circle cx="12" cy="12" r="3"/><path d="m9 3 1 2h4l1-2 3 2-1 2 2 3h2v4h-2l-2 3 1 2-3 2-1-2h-4l-1 2-3-2 1-2-2-3H3v-4h2l2-3-1-2z"/>')};
let rpcTail=Promise.resolve();
let rpcOwner=null;
const pendingTracking=new Set();
window.CDAOperationContext=()=>({busy:ui.busy,closed:ui.closed,owner:ui.actionOwner||'none',owner_request_id:ui.actionRequestId,pending_request_id:ui.pendingTraceId,pending_state:ui.pending?.state,queue_owner:rpcOwner?.method||'none',queue_request_id:rpcOwner?.requestId});
function operationError(code,operation,reason='',blocking=''){
  const error=new Error([code,operation,reason,blocking].filter(Boolean).join(' · '));
  Object.assign(error,{code,operation,reason,blocking_operation:blocking});return error;
}
const diagnosticErrorCode=error=>error?.code||(error?.message==='busy'?'busy':'other');
function credentialErrorMessage(error){const messages={qa_credentials_disabled:tr('合成 QA 禁止保存凭据；请使用独立 Live 模式。','Synthetic QA forbids saving credentials; use separate Live mode.'),credential_value_required:tr('请输入新凭据。','Enter a new credential.'),credential_storage_failed:tr('凭据加密或写入失败，旧凭据保留。','Credential encryption/write failed; existing credential retained.'),ai_endpoint_mismatch:tr('AI 服务与地址不匹配，请检查设置。','AI provider and endpoint do not match.')};return messages[error.code]?messages[error.code]+' ['+error.message+']':error.message;}
function rpc(method,params={},timeoutMs=30000,requestId=ui.actionRequestId||CDAOperations.newId()){
  const trace=(stage,fields={})=>CDAOperations.record(stage,requestId,{operation:method,...CDAOperations.context(),...fields});
  trace('frontend_rpc_prepare',{has_bridge:typeof window.pywebview?.api?.invoke==='function'});
  if(ui.closed){trace('frontend_rpc_rejected',{code:'window_closed'});return Promise.reject(operationError('window_closed',method));}
  const key=method==='set_tracking'?`${params.account_scope}:${params.key}`:null;
  if(key&&pendingTracking.has(key)){trace('frontend_rpc_rejected',{code:'busy',reason:'outcome_pending'});return Promise.reject(operationError('busy',method,'outcome_pending'));}
  let expired=false,dispatched=false;
  const pending=rpcTail.then(async()=>{
    if(expired)throw operationError('request_timeout',method,'expired_before_dispatch');
    if(ui.closed)throw operationError('window_closed',method);
    dispatched=true;
    rpcOwner={method,requestId};trace('frontend_rpc_dispatch');
    const result=await window.pywebview.api.invoke(method,params,{request_id:requestId});
    trace('frontend_rpc_response',{ok:result?.ok===true,code:result?.error||'other',reason:result?.reason||'other',blocking_operation:result?.blocking_operation||'none'});
    if(ui.closed)throw operationError('window_closed',method);
    if(!result?.ok)throw operationError(result?.error||'operation_failed',method,result?.reason,result?.blocking_operation);
    return result.data;
  });
  // A caller deadline does not cancel Python or release its queue slot. Never replay a timed-out write.
  if(key)pendingTracking.add(key);
  const settled=()=>{if(key)pendingTracking.delete(key);if(rpcOwner?.requestId===requestId)rpcOwner=null;trace('frontend_rpc_settled');};
  rpcTail=pending.then(settled,settled);
  return new Promise((resolve,reject)=>{
    const timer=setTimeout(()=>{expired=true;const reason=dispatched?'outcome_pending_reload_to_verify':'expired_before_dispatch';trace('frontend_rpc_timeout',{code:'request_timeout',reason});reject(operationError('request_timeout',method,reason));},timeoutMs);
    pending.then(value=>{clearTimeout(timer);resolve(value);},error=>{clearTimeout(timer);trace('frontend_rpc_rejected',{code:diagnosticErrorCode(error),reason:error.reason||'transport_exception'});reject(error);});
  });
}
window.addEventListener('beforeunload',()=>{ui.closed=true;});
function toast(message){if(ui.closed)return;$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(ui.toastTimer);ui.toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3400);}
async function action(fn,requestId=CDAOperations.newId(),owner='other'){
  if(ui.busy||ui.closed){CDAOperations.record('frontend_guard_rejected',requestId,{operation:owner,...CDAOperations.context(),reason:ui.closed?'window_closed':'frontend_busy'});return;}ui.busy=true;ui.actionRequestId=requestId;ui.actionOwner=owner;CDAOperations.record('action_started',requestId,{operation:owner,...CDAOperations.context()});document.documentElement.setAttribute('aria-busy','true');
  const controls=[...document.querySelectorAll('button[data-action],button[data-state],button[data-save-secret],button[data-theme],button[data-language]')].map(n=>[n,n.disabled]);
  controls.forEach(([n])=>n.disabled=true);document.querySelector('.statuschip').textContent=tr('◉ 正在处理…','◉ Working…');
  try{return await fn();}catch(error){CDAOperations.record('action_failed',requestId,{operation:owner,code:diagnosticErrorCode(error),reason:error.reason||'other'});if(!ui.closed)toast(tr('操作未完成：','Operation not completed: ')+credentialErrorMessage(error));}
  finally{ui.busy=false;CDAOperations.record('action_released',requestId,{operation:owner,busy:false});ui.actionRequestId=null;ui.actionOwner='none';if(!ui.closed){document.documentElement.removeAttribute('aria-busy');controls.forEach(([n,old])=>{if(n.isConnected)n.disabled=old;});if(ui.data)document.querySelector('.statuschip').textContent=syncLabel();}}
}
function statusName(value){return ({'Confirmed Submitted':tr('Canvas 已确认提交','Canvas confirmed submitted'),'Confirmed Not Submitted':tr('确认未提交','Confirmed not submitted'),'Graded':tr('已评分／豁免','Graded / excused'),'Pending / Processing':tr('处理中','Pending / processing'),'Unknown':tr('状态未知','Status unknown'),'Unknown / Unable to Verify':tr('无法确认','Unable to verify')})[value]||e(value);}
const confirmed=t=>['Confirmed Submitted','Graded'].includes(t.status);
function effective(t){return t.local.state==='ignored'?'ignored':t.local.state==='completed'?'complete':confirmed(t)?'verified':'active';}
function relative(t){if(!t.due)return tr('无截止日期','No due date');const m=Math.ceil((Date.parse(t.due)-Date.now())/60000);if(m<0)return tr(`已逾期 ${Math.ceil(-m/60)} 小时`,`${Math.ceil(-m/60)} h overdue`);if(m<60)return tr(`${m} 分钟后`,`${m} min left`);if(m<1440)return tr(`${Math.round(m/60)} 小时后`,`${Math.round(m/60)} h left`);return tr(`${Math.round(m/1440)} 天后`,`${Math.round(m/1440)} days left`);}
const urgent=t=>t.due&&Date.parse(t.due)>=Date.now()&&Date.parse(t.due)-Date.now()<=3600000&&effective(t)==='active';
function badge(t){const s=effective(t);return s==='ignored'?`<span class="tag gray">${tr('已忽略','Ignored')}</span>`:s==='complete'?`<span class="tag amber">${tr('本地已完成','Locally done')}</span>`:s==='verified'?`<span class="tag green">${tr('Canvas 已确认','Canvas confirmed')}</span>`:urgent(t)?`<span class="tag urgent">${tr('临近截止','Due soon')}</span>`:`<span class="tag gray">${tr('待处理','To do')}</span>`;}
function localNote(t){if(t.local.state==='completed')return confirmed(t)?tr('本地完成 · Canvas 已确认','Locally done · Canvas confirmed'):tr('本地已完成，Canvas 尚未确认','Locally completed; Canvas has not confirmed');if(t.local.state==='ignored')return tr('已忽略，提醒已停止','Ignored; reminders stopped');return t.local.content_changed?tr('Canvas 内容已更新，保留你的本地选择','Canvas content updated; local choice preserved'):confirmed(t)?tr('Canvas 已确认收到提交','Canvas has confirmed this submission'):tr('作业要求与 Rubric 可在详情中核对','Review requirements and rubric in details');}
function taskRow(t){return `<article class="task" data-task-key="${e(t.key)}"><div class="taskMain"><div class="taskMeta"><span>${e(t.course)}</span><span class="dot"></span><span>${e(relative(t))}</span>${badge(t)}</div><div class="taskTitle">${e(t.title)}</div><div class="taskNote">Canvas: ${e(statusName(t.status))} · ${e(localNote(t))}</div></div><div class="taskactions"><button class="btn tiny" data-open="${e(t.key)}">${tr('查看详情','View details')}</button><button title="${tr('更多操作','More actions')}" aria-label="${tr('更多操作','More actions')}" class="btn tiny" data-open="${e(t.key)}">···</button></div></article>`;}
function notePanel(){return syncWarning()+` <div class="notePanel"><div class="noteIcon">✦</div><div><h3>${tr('所有提醒以实际状态为准','Reminders follow the actual tracking state')}</h3><p>${tr('本地已完成、已忽略的作业不发送桌面或 PushPlus 提醒；Canvas 原始提交状态始终保留。','Locally completed and ignored assignments do not send desktop or PushPlus reminders. The original Canvas status is retained.')}${ui.data.qa?tr(' 当前为离线合成 QA 数据。',' Offline synthetic QA data.'):''}</p></div></div>`;}
function stats(){const a=ui.data.tasks.filter(t=>effective(t)==='active');return `<div class="stats">${[[tr('待处理作业','Assignments to do'),a.length,tr('仅统计需要追踪的任务','Only tasks that need tracking'),'◷'],[tr('紧急截止','Urgent deadlines'),a.filter(urgent).length,tr('优先检查是否已提交','Check submission status first'),'◴'],[tr('本地已完成','Locally completed'),ui.data.tasks.filter(t=>t.local.state==='completed').length,tr('不代表 Canvas 已确认','Separate from Canvas confirmation'),'✓']].map(([title,n,sub,icon])=>`<div class="stat"><div class="stathead"><span>${title}</span><span class="subtleicon">${icon}</span></div><div class="statnumber">${n}</div><div class="statmeta">${sub}</div></div>`).join('')}</div>`;}
function syncLabel(){return ui.data.qa?tr('◉ 合成 QA 数据 · 离线','◉ Synthetic QA · Offline'):(ui.data.failures.length||ui.data.coverage?.length)?tr('◉ 数据不完整','◉ Incomplete coverage'):tr('◉ 最近同步：','◉ Last sync: ')+formatDate(ui.data.sync.last_success);}
function syncWarning(){
  const failures=ui.data.failures||[],coverage=ui.data.coverage||[];
  const checked=Date.parse(ui.data.sync.last_check),stale=!Number.isFinite(checked)||Date.now()-checked>86400000;
  if(!failures.length&&!coverage.length&&!stale)return '';
  const lines=[...failures,...coverage].map(x=>`${x.course_id} · ${x.kind} · ${x.code}`);
  return `<div class="warn" role="status">${tr('同步状态：部分范围不可用或缓存已过期，不代表没有作业。','Sync status: coverage is incomplete or the cache is stale; this does not mean there are no assignments.')}<br>${e(lines.join(' / ')||tr('请配置 Canvas 并同步。','Configure Canvas and sync.'))}</div>`;
}
function sorted(tasks){const due=t=>{const d=Date.parse(t.due);return Number.isFinite(d)?d:null;};return [...tasks].sort((a,b)=>{const x=due(a),y=due(b);if(x===null)return y===null?a.key.localeCompare(b.key):1;if(y===null)return -1;return (x-y)*(ui.page==='assignments'&&ui.sort==='desc'?-1:1)||a.key.localeCompare(b.key);});}
function list(tasks){return `<div class="tasklist">${tasks.length?sorted(tasks).map(taskRow).join(''):`<div class="empty">${tr('此分类暂无作业。请先配置并同步，或切换筛选。','Nothing here yet. Configure and sync Canvas, or change your filter.')}</div>`}</div>`;}
function today(){return `${stats()}<div class="sectionhead"><h2>${tr('需要你关注的作业','Assignments that need your attention')}</h2><div class="formactions"><button class="btn tiny" data-action="sync">${tr('同步','Sync')}</button><button class="link" data-nav="assignments">${tr('查看全部 →','View all →')}</button></div></div>${list(ui.data.tasks.filter(t=>effective(t)==='active'))}${notePanel()}`;}
function filteredTasks(){const query=ui.query.trim().toLocaleLowerCase();return ui.data.tasks.filter(t=>(ui.filter==='all'||(ui.filter==='verified'?confirmed(t):ui.filter==='unknown'?['Unknown','Unknown / Unable to Verify'].includes(t.status):effective(t)===ui.filter))&&(ui.course==='all'||String(t.course_id)===ui.course)&&(!query||[t.title,t.course,t.local.note||''].join(' ').toLocaleLowerCase().includes(query)));}
function assignments(){const filters=[['active',tr('待处理','To do')],['all',tr('全部作业','All assignments')],['complete',tr('本地已完成','Locally done')],['ignored',tr('已忽略','Ignored')],['verified',tr('已确认提交','Canvas confirmed')],['unknown',tr('状态未知','Unknown')]];return `<div class="fields"><label class="field"><span>${tr('搜索作业','Search assignments')}</span><input id="task-search" maxlength="200" value="${e(ui.query)}" placeholder="${tr('标题、课程或备注','Title, course or note')}"></label><label class="field"><span>${tr('课程','Course')}</span><select id="task-course"><option value="all">${tr('全部课程','All courses')}</option>${ui.data.courses.map(c=>`<option value="${c.id}" ${ui.course===String(c.id)?'selected':''}>${e(c.course_code||c.name)}</option>`).join('')}</select></label><label class="field"><span>${tr('截止时间排序','Sort by due date')}</span><select id="task-sort"><option value="asc" ${ui.sort==='asc'?'selected':''}>${tr('最早优先','Earliest first')}</option><option value="desc" ${ui.sort==='desc'?'selected':''}>${tr('最晚优先','Latest first')}</option></select></label></div><div class="tabs" role="tablist">${filters.map(([k,v])=>`<button role="tab" aria-selected="${k===ui.filter}" data-filter="${k}" class="tab ${ui.filter===k?'active':''}">${v}</button>`).join('')}</div>${list(filteredTasks())}${notePanel()}`;}
function records(){const taskFor=key=>ui.data.tasks.find(t=>t.key===key);return `<div class="panel"><h3>${tr('Canvas 远端核验记录','Canvas verification records')}</h3><p>${tr('只有 Canvas 核验成功才能显示已确认。本地标记不代表提交；超时属于未知。','Only Canvas verification confirms submission. Local choices are separate; a timeout is unknown.')}</p></div><div class="tasklist">${ui.data.history.length?[...ui.data.history].reverse().map(r=>`<article class="task record" data-task-key="${e(r.key)}"><div><div class="taskTitle">${e(taskFor(r.key)?.title||r.key)} · ${e(statusName(r.status))}</div><div class="taskNote">${e(formatDate(r.checked))} · ${e(r.error||'')}</div></div><span class="tag gray">${tr('尝试','Attempt')} ${e(r.attempt??'—')}</span></article>`).join(''):`<div class="empty">${tr('暂无核验记录。','No verification records yet.')}</div>`}</div><div class="panel"><h3>${tr('本地操作记录（不代表 Canvas 提交）','Local actions (not Canvas submissions)')}</h3></div><div class="tasklist">${(ui.data.local_history||[]).map(r=>`<article class="task local-record" data-task-key="${e(r.key)}"><div><div class="taskTitle">${e(taskFor(r.key)?.title||r.key)} · ${e(({tracking:tr('正常追踪','Tracking'),completed:tr('本地已完成','Locally completed'),ignored:tr('已忽略','Ignored')})[r.state]||r.state)}</div><div class="taskNote">${e(formatDate(r.at))} · ${e(r.reason)} · ${e(r.note)}</div></div></article>`).join('')||`<div class="empty">${tr('暂无本地操作。','No local actions yet.')}</div>`}</div>${notePanel()}`;}

function credentialFlag(kind){if(ui.data.qa)return tr('合成 QA：凭据保存禁用','Synthetic QA: credentials disabled');if(kind==='ai'&&ui.data.credential_policy?.ai_legacy_rebind_required)return tr('旧 AI 密钥保留；请按服务重新绑定','Legacy key retained; rebind for this provider');return ui.data.credentials[kind]==='saved'?tr('已安全保存','Securely saved'):ui.data.credentials[kind]==='unreadable'?tr('需重新绑定','Rebind required'):tr('尚未绑定','Not connected');}
function notifications(){const receipt=ui.data.pushplus?.last_test;return `<div class="panel"><div class="row between wrap"><div><h3>${tr('PushPlus 微信提醒','WeChat reminders with PushPlus')}</h3><p>${tr('使用你自己的个人账号和 Token','Use your own personal account and token')}</p></div><span class="tag ${ui.data.credentials.pushplus==='saved'?'green':'amber'}">${credentialFlag('pushplus')}</span></div><div class="divider"></div><p>${tr('需注册 PushPlus、绑定微信并按平台要求实名认证；额度、频率限制及验证费用以官方规则为准。','Register with PushPlus, bind WeChat and complete the platform identity requirements. Quotas, frequency limits and verification fees follow current official terms.')}</p><div class="fields"><label class="field wide"><span>${tr('个人 PushPlus Token','Personal PushPlus token')}</span><input id="pushplus-token" type="password" autocomplete="off" spellcheck="false" placeholder="${tr('已保存的 Token 不会回传到此处','Saved tokens are never returned here')}"></label></div><div class="formactions"><button class="btn" data-show-secret="pushplus-token">${tr('显示／隐藏','Show / hide')}</button><button class="btn primary" data-save-secret="pushplus">${tr('安全保存','Save securely')}</button><button class="btn" data-remove-secret="pushplus">${tr('解绑','Unbind')}</button><button class="btn" data-action="testpush">${tr('发送测试通知','Send test reminder')}</button><button class="btn ghost" data-action="pushportal">${tr('官方入口 ↗','Official portal ↗')}</button></div></div><div class="panel"><h3>${tr('请求与送达状态','Request & delivery status')}</h3><p>${e(receipt?receipt.status+' · '+(receipt.delivery_confirmed?tr('用户确认已收到','User confirmed receipt'):tr('微信送达尚未确认','WeChat delivery unconfirmed')):tr('尚未发送测试请求','No test request yet'))}</p>${receipt?.status==='accepted'&&!receipt.delivery_confirmed?`<button class="btn" data-action="receivedpush">${tr('我确认收到此测试消息','I received this test message')}</button>`:''}<p>${e(JSON.stringify(ui.data.pushplus?.budget||{}))}</p><p>${tr('明确可重试失败最多尝试 3 次，间隔至少 15 分钟；超时等不确定结果不自动重发。接口接受不等于微信已送达。','Explicit retryable failures allow at most 3 attempts, at least 15 minutes apart. Uncertain outcomes are not automatically replayed. API acceptance is not WeChat delivery.')}</p><pre class="contexttext">${e((ui.data.delivery||[]).map(d=>d.channel+' · '+d.status+' · '+formatDate(d.updated)+' · '+tr('尝试 ','Attempts ')+(d.attempts||0)+(d.next_retry_after?' · '+formatDate(d.next_retry_after):'')).join('\n'))}</pre><h3>${tr('提醒规则','Reminder rules')}</h3>${settingRow(tr('截止前提醒','Before the deadline'),tr('当前提前窗口；完整计划可在设置中调整。','Current window; adjust schedules in Settings.'),`<span class="tag green">${ui.data.settings.strong_hours} h</span>`)}${settingRow(tr('截止前 60 分钟紧急模式','60-minute Deadline Guardian'),tr('进入前先检查 Canvas 及本地追踪状态。','Checks Canvas and local tracking before entry.'),`<span class="tag ${ui.data.settings.guardian_enabled?'green':'gray'}">${ui.data.settings.guardian_enabled?tr('已启用','Enabled'):tr('已关闭','Off')}</span>`)}${settingRow(tr('忽略／本地已完成','Ignored / locally completed'),tr('所有提醒渠道立即停止；恢复后遵守原有去重。','Every reminder channel stops; restoring respects existing receipts.'),`<span class="tag green">${tr('统一规则','Always applied')}</span>`)}</div><div class="warn">${tr('接口接受请求不代表微信已送达。电脑关机、休眠或断网会影响本地计划，本程序不是全天候云端服务。','API acceptance does not prove delivery. Shutdown, sleep or offline periods affect local scheduling; this is not an always-on cloud service.')}</div>`;}
function settingRow(title,sub,control){return `<div class="settingrow"><div><strong>${title}</strong><small>${sub}</small></div>${control}</div>`;}
function input(key,title,value,type='text',wide=false){return `<label class="field ${wide?'wide':''}"><span>${title}</span><input data-setting="${key}" type="${type}" value="${e(value??'')}" autocomplete="off"></label>`;}
function selectSetting(key,title,options,valueType='string'){const current=ui.data.settings[key];return `<label class="field"><span>${title}</span><select data-setting="${key}" data-value-type="${valueType}">${options.map(([value,label])=>`<option value="${e(value)}" ${String(current)===String(value)?'selected':''}>${e(label)}</option>`).join('')}</select></label>`;}
function channelsSetting(key,title){const current=ui.data.settings[key].slice().sort().join(',');return `<label class="field"><span>${title}</span><select data-setting="${key}" data-value-type="channels">${[['windows',tr('Windows 通知','Windows notification')],['pushplus',tr('PushPlus 微信','PushPlus WeChat')],['pushplus,windows',tr('Windows + PushPlus','Windows + PushPlus')]].map(([value,label])=>`<option value="${value}" ${current===value?'selected':''}>${label}</option>`).join('')}</select></label>`;}
function toggle(key){const on=ui.data.settings[key];return `<button class="toggle ${on?'on':''}" role="switch" aria-checked="${on}" aria-label="${e(key)}" data-toggle-setting="${key}"></button>`;}
function settings(){const c=ui.data.settings;const tabs=[['appearance',tr('外观与语言','Appearance')],['canvas',tr('Canvas 连接','Canvas')],['reminders',tr('提醒时间','Reminders')],['ai',tr('AI 设置','AI')],['advanced',tr('高级功能','Advanced')]];let content='';if(ui.settingsTab==='appearance')content=`<div class="panel"><h3>${tr('界面设置','Appearance & language')}</h3><p>${tr('两种配色，同一套舒适、清晰的布局。','Two palettes, one calm and consistent layout.')}</p>${settingRow(tr('视觉主题','Theme'),tr('按你的喜好选择，重启后保留。','Saved locally and restored next time.'),`<div class="segmented"><button class="btn ${c.theme==='sage'?'selected':''}" data-theme="sage">Warm Sage</button><button class="btn ${c.theme==='pink'?'selected':''}" data-theme="pink">Soft Pink</button></div>`)}${settingRow(tr('界面语言','Language'),tr('中文与英文使用同一信息结构。','The same information in Chinese and English.'),`<div class="segmented"><button class="btn ${c.language==='zh'?'selected':''}" data-language="zh">中文</button><button class="btn ${c.language==='en'?'selected':''}" data-language="en">English</button></div>`)}${settingRow(tr('默认首页','Start page'),tr('打开后直接查看最紧急的作业。','Start with the assignments that matter first.'),`<span class="tag green">${tr('今日概览','Today')}</span>`)}</div><div class="panel"><h3>${tr('连接与隐私','Connection & privacy')}</h3>${settingRow(tr('Canvas 连接','Canvas connection'),credentialFlag('canvas'),`<button class="btn" data-settings-tab="canvas">${tr('管理连接','Manage connection')}</button>`)}${settingRow(tr('最后成功同步','Last successful sync'),e(formatDate(ui.data.sync.last_success)),`<span class="tag gray">${ui.data.failures.length?tr('部分数据未更新','Some data unavailable'):tr('独立状态记录','Separate sync status')}</span>`)}</div>`;
if(ui.settingsTab==='canvas')content=`<div class="panel"><h3>${tr('Canvas 连接','Connect to Canvas')}</h3><p>${tr('使用学校实例 Base URL 与你自己的合法 Token，凭据通过 Windows DPAPI 保存。','Use the school instance Base URL and your own authorized token. Credentials use Windows DPAPI.')}</p><div class="connectionstatus"><i class="statusdot"></i>${credentialFlag('canvas')}</div><div class="fields">${input('canvas_url',tr('Canvas Base URL','Canvas Base URL'),c.canvas_url,'url',true)}<label class="field wide"><span>Canvas Token</span><input id="canvas-token" type="password" autocomplete="off" placeholder="${tr('留空保留已保存凭据','Leave empty to keep the saved credential')}"></label></div><div class="formactions"><button class="btn primary" data-action="savecanvas">${tr('保存连接','Save connection')}</button><button class="btn" data-show-secret="canvas-token">${tr('显示／隐藏输入','Show / hide input')}</button><button class="btn" data-remove-secret="canvas">${tr('解绑 Canvas','Unbind Canvas')}</button><button class="btn" data-action="identity">${tr('验证账号','Verify identity')}</button><button class="btn" data-action="sync">${tr('立即同步','Sync now')}</button></div><p class="helper">${tr('同步失败会保留已有缓存，并显示失败范围；不会将连接错误当成没有作业。','Failed synchronization preserves the cache and reports unavailable scopes; a connection error is never an empty task list.')}</p></div>`;
if(ui.settingsTab==='reminders')content=`<div class="panel"><h3>${tr('提醒时间','Reminder schedule')}</h3><p>${tr('正常周与考试周计划共用可靠去重，时间以所选时区为准。','Normal and exam schedules share durable deduplication. Times use the configured timezone.')}</p><div class="fields">${input('normal_times',tr('正常周检查时间（逗号分隔）','Normal times (comma separated)'),c.normal_times.join(', '))}${input('exam_times',tr('考试周检查时间','Exam times'),c.exam_times.join(', '))}${input('timezone',tr('时区','Timezone'),c.timezone)}${input('sync_interval_minutes',tr('额外同步间隔（分钟，0 关闭）','Extra sync interval (min; 0 off)'),c.sync_interval_minutes,'number')}${input('strong_hours',tr('截止前窗口（小时）','Before-deadline window (h)'),c.strong_hours,'number')}${input('guardian_minutes',tr('首次紧急提醒（分钟）','First Guardian alert (min)'),c.guardian_minutes,'number')}${input('guardian_repeat_minutes',tr('再次紧急提醒（分钟）','Follow-up Guardian alert (min)'),c.guardian_repeat_minutes,'number')}</div>${settingRow(tr('自动监控','Automatic monitoring'),tr('需要电脑唤醒、已登录及系统计划任务。','Requires an awake, signed-in computer and a scheduled task.'),toggle('monitoring'))}${settingRow(tr('60 分钟紧急模式','Deadline Guardian'),tr('本地完成、忽略和 Canvas 确认提交始终先过滤。','Local completion, ignored and confirmed submissions are excluded first.'),toggle('guardian_enabled'))}${settingRow(tr('逾期追踪','Track overdue tasks'),tr('仅追踪仍需处理的任务。','Only tasks that still need attention.'),toggle('overdue_enabled'))}<div class="formactions"><button class="btn primary" data-action="savesettings">${tr('保存提醒设置','Save reminder settings')}</button></div></div>`;
if(ui.settingsTab==='ai')content=`<div class="panel"><h3>${tr('AI 设置（可选）','AI settings (optional)')}</h3><p>${tr('默认关闭。所有核心作业管理与提醒无需 AI Key。课程材料不会因浏览此页而上传。','Off by default. Core task management and reminders do not require an AI key. Opening this page never uploads course materials.')}</p>${settingRow(tr('启用可选 AI','Optional AI'),tr('需另行同意发送指定课程文本，并可能产生费用。','Requires separate consent to send selected text and may incur fees.'),toggle('ai_enabled'))}<div class="fields">${input('ai_url',tr('服务地址','Provider URL'),c.ai_url,'url',true)}${input('ai_model',tr('模型','Model'),c.ai_model)}<label class="field"><span>API Key</span><input id="ai-token" type="password" autocomplete="off" placeholder="${e(credentialFlag('ai'))}"></label></div><div class="formactions"><button class="btn primary" data-save-secret="ai">${tr('保存 Key','Save key')}</button><button class="btn" data-remove-secret="ai">${tr('删除 Key','Remove key')}</button><button class="btn" data-action="savesettings">${tr('保存 AI 设置','Save AI settings')}</button></div></div>`;
if(ui.settingsTab==='advanced')content=`<div class="panel"><h3>${tr('课程与高级功能','Courses & advanced settings')}</h3><p>${tr('按需展开低频设置，不把所有选项堆在一个长表单中。','Open less frequent options only when needed.')}</p><details class="settingrow"><summary>${tr('课程范围','Course scope')}</summary><div class="fields wide">${ui.data.courses.map(course=>`<label class="row"><input type="checkbox" data-course="${course.id}" ${!c.course_ids||c.course_ids.includes(course.id)?'checked':''}>${e(course.course_code||course.name)}</label>`).join('')||`<span class="muted">${tr('同步后显示课程列表。','Courses appear after synchronization.')}</span>`}</div></details><details class="settingrow"><summary>${tr('周报与逾期策略','Weekly & overdue policy')}</summary><div class="fields">${input('overdue_days',tr('逾期追踪天数','Overdue days'),c.overdue_days,'number')}${input('weekly_time',tr('周报时间','Weekly time'),c.weekly_time,'time')}${input('exam_start',tr('考试周开始','Exam start'),c.exam_start,'date')}${input('exam_end',tr('考试周结束','Exam end'),c.exam_end,'date')}</div></details><div class="formactions"><button class="btn primary" data-action="savesettings">${tr('保存高级设置','Save advanced settings')}</button></div></div><div class="panel"><h3>${tr('本地备份与迁移','Local backup & migration')}</h3><p>${tr('仅导出设置与数据库，不包含凭据。导入前保留恢复备份。','Export settings and database without credentials. Import preserves a recovery backup first.')}</p><div class="formactions"><button class="btn" data-action="backupdata">${tr('导出本地备份…','Export local backup…')}</button><button class="btn" data-action="importdata">${tr('导入备份…','Import backup…')}</button></div></div><div class="notePanel"><div class="noteIcon">✦</div><div><h3>${tr('数据与凭据保持本地','Your data stays local')}</h3><p>${tr('本地状态保存在 SQLite，账号与学校实例分别隔离。当前开发预览不会自动导入或清除真实用户数据。','SQLite stores local choices separately for each account and school instance. This development preview never imports or clears real user data automatically.')}</p></div></div>`;
if(ui.settingsTab==='reminders')content+=`${settingRow(tr('可选 24 小时提醒','Optional 24-hour reminder'),tr('仍需启用后台监控。','Requires background monitoring.'),toggle('guardian_24h_enabled'))}${settingRow(tr('可选 15 分钟提醒','Optional follow-up reminder'),tr('使用上方再次提醒分钟数。','Uses the follow-up minutes above.'),toggle('guardian_repeat_enabled'))}<button class="btn" data-action="schedulerstatus">${tr('检查后台调度状态','Check background scheduler')}</button><pre id="scheduler-result" class="contexttext"></pre><div class="panel"><h3>${tr('检查与通知策略','Checks & notification policy')}</h3><div class="fields">${selectSetting('mode',tr('当前计划模式','Schedule mode'),[['normal',tr('正常周','Normal')],['exam',tr('考试周','Exam')]])}${channelsSetting('channels',tr('通知渠道','Notification channels'))}</div>${settingRow(tr('截止前强提醒','Before-deadline reminders'),tr('使用上方小时窗口和统一过滤规则。','Uses the hour window and unified tracking filters.'),toggle('strong_enabled'))}<p>${tr('考试日期范围会自动覆盖正常周模式。日期与每周计划见高级功能。','Exam date ranges override normal mode. Dates and weekly schedules are under Advanced.')}</p></div>`;
if(ui.settingsTab==='ai')content+=`<div class="panel"><h3>${tr('独立 AI 选项','Independent AI options')}</h3><div class="fields">${selectSetting('ai_provider',tr('服务类型','Provider'),[['DeepSeek','DeepSeek'],['OpenAI','OpenAI'],['Custom',tr('自定义','Custom')]])}</div>${settingRow(tr('自动公告摘要','Automatic announcement summaries'),tr('开启后，每次检查可发送完整公告正文；默认关闭。','When enabled, checks may send full announcement text. Off by default.'),toggle('ai_announcements_enabled'))}${settingRow(tr('AI 周报补充','AI weekly supplement'),tr('开启后会发送课程、任务、状态、日期与链接；默认关闭。','Sends course, task, status, date and link data when enabled. Off by default.'),toggle('ai_weekly_enabled'))}<details><summary>${tr('预算与生成参数','Budget & generation parameters')}</summary><div class="fields">${input('ai_temperature',tr('温度（0–2）','Temperature (0–2)'),c.ai_temperature,'number')}${input('ai_max_tokens',tr('最大输出 Token','Maximum output tokens'),c.ai_max_tokens,'number')}${input('ai_announcement_limit',tr('每次检查摘要上限','Summaries per check'),c.ai_announcement_limit,'number')}${input('ai_daily_budget',tr('每日请求预算','Daily request budget'),c.ai_daily_budget,'number')}</div></details><div class="formactions"><button class="btn primary" data-action="savesettings">${tr('保存 AI 设置','Save AI settings')}</button><button class="btn" data-action="testai">${tr('测试连接…','Test connection…')}</button><button class="btn" data-action="announcements">${tr('公告与逐条摘要','Announcements & summaries')}</button></div><p class="helper">${tr('修改服务类型后请核对地址和模型；不会自动调用服务。','Check the URL and model after changing provider. No automatic test request is made.')}</p></div>`;
if(ui.settingsTab==='advanced')content+=`<div class="panel"><h3>${tr('数据位置与版本','Data locations & version')}</h3><p>${e(ui.data.application?.version||'1.2')}</p><p style="overflow-wrap:anywhere">${tr('数据库：','Database: ')}${e(ui.data.application?.database||'')}</p><p style="overflow-wrap:anywhere">${tr('启动日志：','Startup logs: ')}${e(ui.data.application?.logs||'')}</p><p>${tr('课程缓存未额外加密；备份不包含凭据，请仅向可信对象分享。','Course caches are not separately encrypted. Backups exclude credentials; share only with trusted recipients.')}</p></div><div class="panel"><h3>${tr('课程与周报策略','Course & weekly policy')}</h3>${settingRow(tr('包含已结束课程','Include ended courses'),tr('下次同步时生效。','Applies on the next synchronization.'),toggle('include_ended'))}${settingRow(tr('启用每周报告','Weekly report'),tr('本地生成；AI 补充需另行开启。','Generated locally. AI supplementation is a separate option.'),toggle('weekly_enabled'))}<div class="fields">${selectSetting('weekly_day',tr('周报星期','Weekly day'),[0,1,2,3,4,5,6].map((v)=>[v,[tr('星期一','Monday'),tr('星期二','Tuesday'),tr('星期三','Wednesday'),tr('星期四','Thursday'),tr('星期五','Friday'),tr('星期六','Saturday'),tr('星期日','Sunday')][v]]),'number')}${channelsSetting('weekly_channels',tr('周报渠道','Weekly channels'))}</div><div class="formactions"><button class="btn primary" data-action="savesettings">${tr('保存高级设置','Save advanced settings')}</button><button class="btn" data-action="weeklypreview">${tr('本地周报预览','Local weekly preview')}</button><button class="btn" data-action="announcements">${tr('查看课程公告','Read course announcements')}</button></div></div>`;
return `<div class="settingnav" role="tablist">${tabs.map(([key,title])=>`<button class="tab ${ui.settingsTab===key?'active':''}" data-settings-tab="${key}">${title}</button>`).join('')}</div>${content}`;}
function formatDate(value){return value?new Intl.DateTimeFormat(ui.data.settings.language==='zh'?'zh-CN':'en-AU',{dateStyle:'medium',timeStyle:'short',timeZone:ui.data.settings.timezone}).format(new Date(value)):tr('尚未同步','Not synchronized');}
function render(){if(!ui.data)return;document.documentElement.dataset.theme=ui.data.settings.theme;document.documentElement.lang=ui.data.settings.language==='zh'?'zh-CN':'en';const names={today:tr('今日概览','Today'),assignments:tr('所有作业','All assignments'),records:tr('提交记录','Submission history'),notifications:tr('微信提醒','WeChat reminders'),settings:tr('设置','Settings')};document.querySelectorAll('.navitem').forEach(node=>{const key=node.dataset.nav;node.querySelector('.ico').innerHTML=icons[key];node.querySelector('span:not(.ico):not(.count)').textContent=names[key];node.classList.toggle('active',key===ui.page);node.setAttribute('aria-label',names[key]);if(key===ui.page)node.setAttribute('aria-current','page');else node.removeAttribute('aria-current');});$('pending-count').textContent=ui.data.tasks.filter(t=>effective(t)==='active').length;const day=new Intl.DateTimeFormat(ui.data.settings.language==='zh'?'zh-CN':'en',{weekday:'long',timeZone:ui.data.settings.timezone}).format(new Date());$('eyebrow').textContent=ui.page==='today'?day+tr(' · 今日工作台',' · Your workspace'):(['today','assignments','records'].includes(ui.page)?'WORKSPACE':'PREFERENCES')+' · '+names[ui.page];$('pagetitle').textContent=ui.page==='today'?tr('今天先做什么？','What matters today?'):names[ui.page];document.querySelector('.statuschip').textContent=syncLabel();document.querySelector('.toptools .iconbtn').innerHTML=icons.settings;document.querySelector('.sidebarfoot').innerHTML=`<div><i class="statusdot"></i>${ui.data.qa?tr('离线合成测试','Offline synthetic QA'):tr('本地工作台','Local workspace')}</div><div>${ui.data.qa?tr('未连接 Canvas / PushPlus','No Canvas / PushPlus connection'):credentialFlag('canvas')}</div>`;$('page').innerHTML=({today,assignments,records,notifications,settings})[ui.page]();document.querySelector('.footer').textContent='Canvas Deadline Agent · v1.2'+(ui.data.qa?tr(' · 合成 QA 数据，不操作真实账户',' · Synthetic QA data; no live account access'):'');}
async function refresh(requestId=ui.actionRequestId||CDAOperations.newId()){CDAOperations.record('refresh_started',requestId,{operation:'get_state'});try{const result=await rpc('get_state',{},30000,requestId);if(ui.closed)return;ui.data=result;render();CDAOperations.record('refresh_succeeded',requestId,{operation:'get_state',ok:true});}catch(error){CDAOperations.record('refresh_failed',requestId,{operation:'get_state',code:error.code||'other'});throw error;}}
function closeDrawer(){const selected=ui.selected;const release=selected&&ui.data?.account_scope?rpc('workspace',{operation:'revoke',...taskArgs()}):Promise.resolve();release.catch(error=>toast(tr('撤销文件授权未完成：','File access revocation not completed: ')+error.message));$('scrim').classList.remove('show');$('drawer').classList.remove('show');$('drawer').inert=true;$('drawer').setAttribute('aria-hidden','true');document.querySelector(`[data-open="${selected}"]`)?.focus();ui.selected=null;return release;}
function modal(html){ui.modalOpener=document.activeElement;$('modal').innerHTML=html;$('overlay').classList.add('show');$('modal').querySelector('button,input,select')?.focus();}
function closeModal(){$('overlay').classList.remove('show');ui.pending=null;if(ui.modalOpener?.isConnected)ui.modalOpener.focus();}
function drawer(key){const t=ui.data.tasks.find(t=>t.key===key);if(!t)return;ui.selected=key;$('drawer').innerHTML=`<div class="drawerHead"><span class="kicker">${tr('作业详情','Assignment details')}</span><button class="iconbtn" data-close="drawer" aria-label="${tr('关闭详情','Close details')}">×</button></div><div class="kicker">${e(t.course)} · ${e(relative(t))}</div><h2>${e(t.title)}</h2>${badge(t)}<div class="divider"></div><div class="inlineValue"><span>${tr('Canvas 原始状态','Canvas status')}</span><strong>${e(statusName(t.status))}</strong></div><div class="inlineValue"><span>${tr('本地追踪状态','Local tracking')}</span><strong>${e(localNote(t))}</strong></div><div class="inlineValue"><span>${tr('截止时间','Due date')}</span><strong>${e(t.due?formatDate(t.due):tr('无截止日期','No due date'))}</strong></div><div class="divider"></div><div class="inlineValue"><span>${tr('本地备注','Local note')}</span><strong>${e(t.local.note||'—')}</strong></div><div class="inlineValue"><span>${tr('最近核验','Last verification')}</span><strong>${e(t.verification?.checked?statusName(t.verification.status)+' · '+formatDate(t.verification.checked):tr('尚未核验','Not verified'))}</strong></div><strong>${tr('任务说明与 Rubric','Requirements & rubric')}</strong><div id="context-body"><p>${tr('按需从 Canvas 读取要求，不会自动上传或提交。','Read requirements from Canvas on demand. No automatic upload or submission.')}</p></div><button class="btn full" data-action="context">${tr('读取作业要求','Load requirements')}</button><div class="actionGroup" style="margin-top:10px"><button class="btn" data-action="copyprompt">${tr('复制 Prompt','Copy prompt')}</button><button class="btn" data-action="prompt">${tr('生成 Prompt','Generate prompt')}</button><button class="btn" data-action="reviewfiles">${tr('选择文件检查','Review selected files')}</button></div><button class="btn full" data-action="exportprompt">${tr('导出 Prompt…','Export prompt…')}</button><details class="copilotoptions"><summary>${tr('材料、工作区与云端审阅','Materials, workspace & cloud review')}</summary><p>${tr('文件只读授权保留至撤销或关闭详情；云端发送另需全文预览。','Read-only file access lasts until revoked or details close. Cloud transfer requires a separate full-text preview.')}</p><div class="actionGroup"><button class="btn" data-action="wsfiles">${tr('选择文件…','Select files…')}</button><button class="btn" data-action="wsfolder">${tr('选择文件夹…','Select folder…')}</button><button class="btn" data-action="copyworkspace">${tr('复制工作区 Prompt','Copy workspace prompt')}</button><button class="btn" data-action="wsprompt">${tr('工作区 Prompt','Workspace prompt')}</button><button class="btn" data-action="wsrevoke">${tr('撤销文件授权','Revoke file access')}</button><button class="btn" data-action="wsexportpreview">${tr('导出工作区预览','Preview workspace export')}</button><button class="btn" data-action="wscloudpreview">${tr('预览云端审阅全文','Preview full cloud transfer')}</button></div><button class="btn full" data-action="wsdownload">${tr('下载关联 Canvas 附件…','Download linked Canvas materials…')}</button></details><div class="divider"></div><strong>${tr('管理此作业','Manage this assignment')}</strong><div class="actionGroup" style="margin-top:12px"><button class="btn" data-state="completed">✓ ${tr('本地已完成','Locally completed')}</button><button class="btn" data-state="ignored">⊘ ${tr('忽略此作业','Ignore assignment')}</button></div><button class="btn full" data-state="tracking">${tr('恢复正常追踪','Restore tracking')}</button><div class="divider"></div>${urgent(t)?`<button class="btn full" data-action="emergency">${tr('60 分钟紧急准备','60-minute preparation')}</button>`:''}<strong>${tr('提交核验','Submission verification')}</strong><button class="btn primary full" data-action="verify">${tr('核对 Canvas 状态','Verify Canvas status')}</button><button class="btn full" data-action="opencanvas">${tr('打开官方 Canvas 页面 ↗','Open official Canvas page ↗')}</button><div class="warn" style="margin-top:16px">${tr('本地完成与忽略会停止所有提醒，但不会改变 Canvas 原始记录；网络超时保留为无法确认。','Local completion and ignoring stop all reminders without changing Canvas. A timeout remains unconfirmed.')}</div>`;$('scrim').classList.add('show');$('drawer').classList.add('show');$('drawer').inert=false;$('drawer').setAttribute('aria-hidden','false');$('drawer').querySelector('button').focus();}
function taskArgs(){return {key:ui.selected,account_scope:ui.data.account_scope};}
function stateModal(state,requestId=CDAOperations.newId()){ui.pendingTraceId=requestId;CDAOperations.record('state_modal_open',requestId,{operation:'set_tracking',state});const t=ui.data.tasks.find(t=>t.key===ui.selected);ui.pending={state,...taskArgs()};modal(`<h3>${state==='tracking'?tr('恢复正常追踪','Restore tracking'):state==='ignored'?tr('忽略此作业','Ignore assignment'):tr('标记为本地已完成','Mark locally completed')}</h3><p>${e(t.title)}</p><p>${tr('只改变本地提醒，不修改 Canvas 记录。你可以随时恢复。','Only local tracking changes; the Canvas record stays intact. You can restore tracking at any time.')}</p>${state==='tracking'?'':`<label class="label">${tr('原因（可选）','Reason (optional)')}</label><select id="reason"><option value="">${tr('不填写','No reason')}</option><option value="other_submission">${tr('已通过其他方式提交','Submitted elsewhere')}</option><option value="group_submission">${tr('小组成员统一提交','Group submission')}</option><option value="optional">${tr('可选任务','Optional task')}</option><option value="other">${tr('其他','Other')}</option></select><label class="label">${tr('备注（可选）','Note (optional)')}</label><textarea id="localnote" maxlength="500" placeholder="${tr('简短备注，最多 500 字','Brief note, up to 500 characters')}">${e(t.local.note||'')}</textarea>`}<div class="row between"><button class="btn" data-close="modal">${tr('取消','Cancel')}</button><button class="btn primary" data-action="confirmstate">${tr('确认','Confirm')}</button></div>`);}
async function preferences(changes){await rpc('save_settings',{settings:changes});await refresh();}
function collectSettings(){const result={};document.querySelectorAll('[data-setting]').forEach(node=>{const key=node.dataset.setting;let value=node.value;if(['normal_times','exam_times'].includes(key))value=value.split(',').map(s=>s.trim()).filter(Boolean);else if(node.type==='number'||node.dataset.valueType==='number')value=Number(value);else if(node.dataset.valueType==='channels')value=value.split(',');result[key]=value;});const courses=[...document.querySelectorAll('[data-course]')];if(courses.length)result.course_ids=courses.filter(n=>n.checked).map(n=>Number(n.dataset.course));return result;}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;const clickRequestId=CDAOperations.forEvent(event);if(button.disabled||ui.busy||ui.closed)return;const d=button.dataset;if(d.nav){closeDrawer();ui.page=d.nav;render();document.querySelector('.app').scrollTop=0;}if(d.filter){ui.filter=d.filter;render();}if(d.open)drawer(d.open);if(d.close==='drawer')closeDrawer();if(d.close==='modal')closeModal();if(d.settingsTab){ui.settingsTab=d.settingsTab;render();}if(d.theme)action(()=>preferences({theme:d.theme}));if(d.language)action(()=>preferences({language:d.language}));if(d.state)stateModal(d.state,clickRequestId);if(d.showSecret){const node=$(d.showSecret);node.type=node.type==='password'?'text':'password';}if(d.saveSecret)action(async()=>{const node=$(d.saveSecret==='pushplus'?'pushplus-token':'ai-token');try{const value=node.value;node.value='';if(d.saveSecret==='ai'&&!ui.data.qa)await rpc('save_settings',{settings:collectSettings()});await rpc('save_credential',{kind:d.saveSecret,value});if(d.saveSecret==='pushplus')await preferences({channels:[...new Set([...ui.data.settings.channels,'pushplus'])]});await refresh();toast(tr('已安全保存','Securely saved'));}finally{node.value='';}});if(d.removeSecret)modal(`<h3>${tr('解绑凭据','Remove saved credential')}</h3><p>${tr('仅删除本机所保存的凭据，不改变第三方账号。','Remove only the saved local credential, leaving the provider account intact.')}</p><div class="row between"><button class="btn" data-close="modal">${tr('取消','Cancel')}</button><button class="btn primary" data-remove-confirmed="${e(d.removeSecret)}">${tr('确认解绑','Remove')}</button></div>`);if(d.removeConfirmed)action(async()=>{await rpc('remove_credential',{kind:d.removeConfirmed});closeModal();await refresh();});if(d.toggleSetting){const key=d.toggleSetting;if(['ai_enabled','ai_announcements_enabled','ai_weekly_enabled'].includes(key)&&!ui.data.settings[key]){ui.pendingAiSetting=key;modal(`<h3>${tr('启用可选 AI','Enable optional AI')}</h3><p>${tr('启用当前 AI 选项可能在后续检查或周报时向所配置服务发送课程文本，并产生费用；核心提醒无需 AI。是否同意？','The selected AI option may send course text during later checks or weekly reports and may incur fees. Core reminders do not need AI. Do you consent?')}</p><div class="row between"><button class="btn" data-close="modal">${tr('取消','Cancel')}</button><button class="btn primary" data-action="consentai">${tr('同意并启用','Consent & enable')}</button></div>`);}else action(()=>preferences({[key]:!ui.data.settings[key]}));}if(d.action)action(async()=>{await extraAction(d.action);if(d.action==='confirmstate'){const params={...ui.pending,reason:$('reason')?.value||'',note:$('localnote')?.value||''};await rpc('set_tracking',params);closeModal();await closeDrawer();await refresh();toast(tr('本地选择已保存','Local choice saved'));}if(d.action==='verify'){const r=await rpc('verify_submission',taskArgs());await refresh();drawer(ui.selected);toast(statusName(r.status));}if(d.action==='context'){const args=taskArgs();const r=await rpc('assignment_context',args);if(ui.selected===args.key&&ui.data.account_scope===args.account_scope)renderContext(r);}if(d.action==='prompt'){const r=await rpc('generate_prompt',taskArgs());const area=document.createElement('textarea');area.readOnly=true;area.className='contexttext';area.style.width='100%';area.style.minHeight='230px';area.value=r.text;$('context-body').replaceChildren(area);toast(tr('Prompt 已在本地生成，可选中文字复制','Prompt generated locally; select text to copy'));}if(['reviewfiles','exportprompt','backupdata','importdata'].includes(d.action)){const methods={reviewfiles:'review_files',exportprompt:'export_prompt',backupdata:'backup_data',importdata:'import_backup'};ui.pendingNative={method:methods[d.action],params:['reviewfiles','exportprompt'].includes(d.action)?taskArgs():{}};modal(`<h3>${tr('确认本地操作','Confirm local action')}</h3><p>${d.action==='reviewfiles'?tr('你将自行选择需要检查的文件。只做静态检查，不执行或上传内容。','You select the files to inspect. Static checks only, without execution or upload.'):d.action==='importdata'?tr('将先备份当前数据，再导入你选择的本地备份；不导入凭据，监控将关闭。','Current data is backed up before importing your selected local backup. Credentials are excluded and monitoring is disabled.'):tr('接下来由你选择保存位置，不上传到任何服务。','You choose a save location. No data is uploaded.')}</p><div class="row between"><button class="btn" data-close="modal">${tr('取消','Cancel')}</button><button class="btn primary" data-action="confirmednative">${tr('继续选择','Choose location / files')}</button></div>`);}if(d.action==='confirmednative'){const p=ui.pendingNative;const r=await rpc(p.method,{...p.params,confirmed:true});closeModal();if(r.status==='reviewed'){const pre=document.createElement('pre');pre.className='contexttext';pre.textContent=JSON.stringify(r,null,2);$('context-body').replaceChildren(pre);}else {await refresh();toast(tr('本地操作：','Local action: ')+r.status);}}if(d.action==='opencanvas'){const r=await rpc('open_official',{destination:'canvas',...taskArgs()});if(!r.opened)toast(r.status||tr('QA 模式不打开浏览器','QA does not open browsers'));}if(d.action==='pushportal'){const r=await rpc('open_official',{destination:'pushplus'});if(!r.opened)toast(r.status||tr('QA 模式不打开浏览器','QA does not open browsers'));}if(d.action==='savesettings'){await preferences(collectSettings());toast(tr('设置已保存','Settings saved'));}if(d.action==='savecanvas'){const node=$('canvas-token');const value=node?.value||'';if(node)node.value='';await rpc('save_settings',{settings:collectSettings()});if(value)await rpc('save_credential',{kind:'canvas',value});await refresh();toast(tr('连接设置已保存','Connection settings saved'));}if(d.action==='identity'){const r=await rpc('test_identity');toast(r.status==='qa_offline'?tr('QA 离线模式，不访问真实账号','Offline QA; no live account access'):tr('账号验证成功','Identity verified'));}if(d.action==='sync'){toast(tr('正在同步 Canvas…','Synchronizing Canvas…'));const r=await rpc('sync');await refresh();toast(tr('同步状态：','Sync status: ')+r.status);}if(d.action==='testpush')modal(`<h3>${tr('发送一条测试提醒？','Send one test reminder?')}</h3><p>${tr('将调用你自己的 PushPlus 账号。消息仅含测试文字，不含课程内容；API 接受不等于送达。','Uses your personal PushPlus account. The message contains test text only. API acceptance does not prove delivery.')}</p><div class="row between"><button class="btn" data-close="modal">${tr('取消','Cancel')}</button><button class="btn primary" data-action="confirmedpush">${tr('确认发送','Send test')}</button></div>`);if(d.action==='confirmedpush'){const r=await rpc('test_pushplus',{confirmed:true});closeModal();await refresh();toast(tr('请求结果（送达未确认）：','Request result (delivery unconfirmed): ')+r.status+' · '+Object.values(r.channels||{}).join(', '));}if(d.action==='consentai'){closeModal();await preferences({[ui.pendingAiSetting||'ai_enabled']:true,ai_consent:true});}},d.action==='confirmstate'?ui.pendingTraceId:clickRequestId,d.action);});
$('scrim').addEventListener('click',closeDrawer);$('overlay').addEventListener('click',event=>{if(event.target===$('overlay'))closeModal();});document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeModal();closeDrawer();}if(event.key==='Tab'){const host=$('overlay').classList.contains('show')?$('modal'):$('drawer').classList.contains('show')?$('drawer'):null;if(host){const nodes=[...host.querySelectorAll('button,input,select,textarea,a[href]')].filter(n=>!n.disabled);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}}});
let initialBootStarted=false;
async function startUi(){
  if(initialBootStarted||!window.pywebview?.api?.invoke)return;
  initialBootStarted=true;window.CDAStartup?.bridge();
  try{
    if(window.CDAStartup)await window.CDAStartup.domReady;
    await refresh();
    if(document.readyState==='loading')await new Promise(resolve=>document.addEventListener('DOMContentLoaded',resolve,{once:true}));
    window.CDAStartup?.ready();
  }catch{window.CDAStartup?.fail('backend_bootstrap_failed');}
}
window.addEventListener('pywebviewready',startUi);
// Explicit user shortcut; works even when a business action is blocked. No downloads or bridge calls.
document.addEventListener('keydown',event=>{if(event.ctrlKey&&event.shiftKey&&event.code==='KeyD'){
  event.preventDefault();modal('<h3>QA operation evidence / 操作诊断</h3><p>Ctrl+A / Ctrl+C · Esc 关闭</p><textarea id="operation-evidence" class="contexttext" readonly aria-label="QA operation evidence"></textarea>');
  $('operation-evidence').value=CDAOperations.exportText();$('operation-evidence').focus();
}});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>{if(window.pywebview?.api?.invoke)startUi();},{once:true});
else if(window.pywebview?.api?.invoke)startUi();

function reportModal(title,body){modal(`<h3>${e(title)}</h3><pre class="contexttext">${e(body)}</pre><button class="btn" data-close="modal">${tr('关闭','Close')}</button>`);}
async function extraAction(name){await workspaceAction(name);
  if(['copyprompt','copyworkspace'].includes(name)){const r=await rpc('copy_prompt',{...taskArgs(),mode:name==='copyprompt'?'standard':'workspace',confirmed:true});toast(tr('复制结果：','Copy result: ')+r.status);}
  if(name==='emergency'){const r=await rpc('emergency_prepare',taskArgs());reportModal(tr('紧急准备','Emergency preparation'),r.eligible?r.steps.join('\n'):tr('此任务不在当前有效追踪窗口。','This task is outside the active preparation window.'));}
  if(name==='schedulerstatus'){const r=await rpc('runtime_status');if($('scheduler-result'))$('scheduler-result').textContent=JSON.stringify(r,null,2);}
  if(name==='receivedpush'){const r=await rpc('confirm_push_received',{receipt_id:ui.data.pushplus.last_test.receipt_id,confirmed:true});await refresh();toast(r.status);}

  if(name==='weeklypreview'){const r=await rpc('weekly_preview');reportModal(tr('本地缓存周报预览','Cached weekly preview'),r.text);}
  if(name==='announcements'){const r=await rpc('announcements');ui.announcementScope=r.account_scope;ui.announcements=r.items;modal(`<h3>${tr('课程公告','Course announcements')}</h3><p>${tr('查看正文不会触发 AI 请求。','Reading announcements never triggers an AI request.')}</p><div class="announcementlist">${r.items.map(a=>`<button class="btn full" data-announcement="${e(a.key)}">${e(a.course)} · ${e(a.title)}</button>`).join('')||tr('暂无缓存公告。','No cached announcements.')}</div><button class="btn" data-close="modal">${tr('关闭','Close')}</button>`);}
  if(['summarygenerate','summaryforce','testai'].includes(name)){ui.pendingAiRequest=name;modal(`<h3>${tr('确认 AI 请求','Confirm AI request')}</h3><p>${name==='testai'?tr('将向已配置服务发送合成测试文字，可能计费。','Sends synthetic test text to the configured provider and may incur fees.'):tr('将向已配置服务发送所选公告的完整正文，可能计费。重新生成会发起新的计费请求。','Sends the full selected announcement to the configured provider and may incur fees. Force regeneration starts a new paid request.')}</p><div class="row between"><button class="btn" data-close="modal">${tr('取消','Cancel')}</button><button class="btn primary" data-action="confirmedai">${tr('确认发送','Confirm request')}</button></div>`);}
  if(name==='confirmedai'){const type=ui.pendingAiRequest;const r=type==='testai'?await rpc('test_ai',{confirmed:true}):await rpc('announcement_summary',{key:ui.announcement.key,account_scope:ui.announcementScope,generate:true,force:type==='summaryforce',confirmed:true});reportModal('AI · '+tr('请人工核对','Verify manually'),r.text);}
}
document.addEventListener('click',event=>{const key=event.target.closest('[data-announcement]')?.dataset.announcement;if(!key)return;action(async()=>{const a=ui.announcements.find(a=>a.key===key);ui.announcement=a;const r=await rpc('announcement_summary',{key,account_scope:ui.announcementScope,generate:false,force:false,confirmed:false});modal(`<h3>${e(a.title)}</h3><pre class="contexttext">${e(a.body)}</pre><div class="divider"></div><pre class="contexttext">${e(r.text)}</pre><div class="formactions"><button class="btn" data-action="summarygenerate">${tr('生成／读取缓存…','Generate / read cache…')}</button><button class="btn" data-action="summaryforce">${tr('重新生成（计费）…','Force regenerate (paid)…')}</button><button class="btn" data-close="modal">${tr('关闭','Close')}</button></div>`);});});

async function workspaceAction(name){
  const call=(operation,extra={})=>rpc('workspace',{operation,...taskArgs(),...extra});
  const show=r=>{const pre=document.createElement('pre');pre.className='contexttext';pre.textContent=r.text||JSON.stringify(r,null,2);$('context-body').replaceChildren(pre);};
  const operations={wsfiles:'select_files',wsfolder:'select_folder',wsdownload:'download_materials'};
  if(operations[name]){ui.pendingWorkspace={operation:operations[name]};modal(`<h3>${tr('确认只读材料操作','Confirm read-only material operation')}</h3><p>${name==='wsdownload'?tr('从 Canvas 获取已关联的附件并解析，不执行文件。若跳转到外部 HTTPS 来源，将再次询问。','Downloads and parses the linked Canvas materials without execution. External HTTPS redirect hosts require a separate confirmation.'):tr('由你选择具体文件或项目文件夹，授权只读解析。不会执行文件，也不会自动上传。关闭详情或撤销授权后停止访问。','You choose exact files or a project folder for read-only parsing. No execution or automatic upload. Closing details or revoking access ends the grant.')}</p><div class="row between"><button class="btn" data-close="modal">${tr('取消','Cancel')}</button><button class="btn primary" data-action="wsconfirmed">${tr('确认继续','Continue')}</button></div>`);}
  if(name==='wsconfirmed'){const pending=ui.pendingWorkspace;const r=await call(pending.operation,{confirmed:true,...(pending.allow_hosts?{allow_hosts:pending.allow_hosts}:{})});closeModal();show(r);if(r.pending_hosts?.length){ui.pendingWorkspace={operation:'download_materials',allow_hosts:r.pending_hosts};modal(`<h3>${tr('确认附件来源','Confirm material hosts')}</h3><p>${tr('Canvas 请求转向以下 HTTPS 主机；不会发送 Canvas Token。','Canvas redirected to these HTTPS hosts. The Canvas token is not forwarded.')}</p><pre class="contexttext">${e(r.pending_hosts.join('\n'))}</pre><div class="row between"><button class="btn" data-close="modal">${tr('取消','Cancel')}</button><button class="btn primary" data-action="wsconfirmed">${tr('允许这些来源','Allow these hosts')}</button></div>`);}}
  if(name==='wsprompt')show(await call('workspace_prompt'));
  if(name==='wsrevoke'){await call('revoke');$('context-body').textContent=tr('文件授权已撤销。','File access revoked.');}
  if(name==='wsexportpreview'){const r=await call('preview_export');ui.workspaceExportTicket=r.ticket;modal(`<h3>${tr('工作区导出清单','Workspace export manifest')}</h3><p>${tr('包含课程材料及可能的已授权路径，分享前请检查。将创建新文件夹，不合并已有目录。','Contains course materials and possibly authorized paths. Review before sharing. Creates a new folder without merging existing content.')}</p><pre class="contexttext">${e(r.files.join('\n'))}</pre><div class="row between"><button class="btn" data-close="modal">${tr('取消','Cancel')}</button><button class="btn primary" data-action="wsexport">${tr('选择父目录并导出','Choose parent & export')}</button></div>`);}
  if(name==='wsexport'){const r=await call('export',{confirmed:true,ticket:ui.workspaceExportTicket});closeModal();show(r);}
  if(name==='wscloudpreview'){const r=await call('preview_cloud');ui.workspaceCloudTicket=r.ticket;modal(`<h3>${tr('云端传输全文预览','Exact cloud transfer preview')}</h3><p>${tr('以下全文将发送至你配置的 AI 服务，可能计费。点击发送前不会调用服务。AI 输出必须人工核对。','The exact text below will be sent to your configured AI service and may incur fees. No request before Send. Verify AI output manually.')}</p><pre class="contexttext">${e(r.text)}</pre><div class="row between"><button class="btn" data-close="modal">${tr('取消','Cancel')}</button><button class="btn primary" data-action="wscloudsend">${tr('发送以上全文','Send displayed text')}</button></div>`);}
  if(name==='wscloudsend'){const r=await call('send_cloud',{confirmed:true,ticket:ui.workspaceCloudTicket});reportModal(tr('AI 审阅，请人工核对','AI review; verify manually'),r.text);}
}

function renderContext(r){
  const pre=document.createElement('pre');pre.className='contexttext';
  pre.textContent=[r.requirements||tr('无描述','No description'),tr('提交方式：','Submission types: ')+(r.submission_types||[]).join(', '),tr('允许扩展名：','Allowed extensions: ')+(r.allowed_extensions||[]).join(', '),r.rubric_status||'',JSON.stringify(r.rubric||[],null,2),(r.missing||[]).join('\n'),r.policy_status||''].join('\n\n');
  $('context-body').replaceChildren(pre);
  for(const file of r.files||[]){const b=document.createElement('button');b.className='btn full';b.dataset.attachment=String(file.file_id);b.textContent=tr('Canvas 附件 ','Canvas attachment ')+(file.name||file.file_id)+' · '+(file.status||'');$('context-body').append(b);}
}
document.addEventListener('input',event=>{if(event.target.id==='task-search'){ui.query=event.target.value;document.querySelector('#page .tasklist').outerHTML=list(filteredTasks());}});
document.addEventListener('change',event=>{if(event.target.dataset.setting==='ai_provider'){const preset={OpenAI:'https://api.openai.com/v1',DeepSeek:'https://api.deepseek.com'}[event.target.value];const field=document.querySelector('[data-setting="ai_url"]');if(preset&&field)field.value=preset;return;}if(event.target.id==='task-course')ui.course=event.target.value;else if(event.target.id==='task-sort')ui.sort=event.target.value;else return;document.querySelector('#page .tasklist').outerHTML=list(filteredTasks());});
document.addEventListener('click',event=>{
  const button=event.target.closest('button');
  if(button?.dataset.attachment)action(()=>rpc('open_official',{destination:'attachment',file_id:Number(button.dataset.attachment),...taskArgs()}));
  if(!button&&!event.target.closest('input,select,textarea,a')){const card=event.target.closest('[data-task-key]');if(card)drawer(card.dataset.taskKey);}
});
